// Table tab (§9.5): Data / Structure / DDL sub-tabs. The data comes from
// the shared connection (§3.1) with the same events as execute; the
// structure and the DDL from introspection via TanStack Query, like the tree.
//
// Server-side sort and filters (decision 10, second half): explicit action
// — context menu on the header, "+ Filter" in the bar, "filter by this
// value" from the cell menu; never the local sort click — which becomes a
// re-query with `ORDER BY`/`WHERE` generated by the backend. The generated
// SELECT always stays visible under the filters.
import { useEffect, useMemo, useRef, useState } from "react";
import { useIsFetching, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  AppendTo,
  BatchUpdateOut,
  CellAssign,
  ColumnFilter,
  OrderBy,
  ErrorOut,
  emptyTableQuery,
  FilterOp,
  ForeignKeyOut,
  ipc,
  Profile,
  RowUpdate,
  TableQuery,
  TableWrite,
  isDefaultCell,
  DEFAULT_CELL,
  PendingValue,
} from "./ipc";
import {
  useStore,
  connById,
  sharedBusyTab,
  tableMayHaveMore,
  TableRef,
  TableSub,
  TabUi,
  StatementUi,
  PendingEdits,
  NewRow,
  pendingRowId,
  unsavedCount,
} from "./store";
import { locale, t, tMsg } from "./i18n";
import { ErrorPanel, StatementPane } from "./ResultPane";
import { RunningNotice } from "./RunningNotice";
import { cacheFor, dropCache } from "./rowCache";
import { RowLinks } from "./RowPanel";
import { makePermanent, newSqlTab, newTableTab, persistWorkspace, releaseTabResults } from "./tabs";
import { asErrorOut } from "./errors";
import { guardUnsaved, numericColumns, pendingToWrites, settleWrites } from "./pending";
import {
  IconChevronLeft,
  IconChevronRight,
  IconDuplicate,
  IconFilter,
  IconPlus,
  IconRefresh,
  IconSort,
  IconTrash,
  IconX,
} from "./icons";
import WhereInput, { WhereInputHandle } from "./WhereInput";
import FilterAdd, { FilterAddHandle } from "./FilterAdd";
import SqlPreview from "./SqlPreview";
import SortChips from "./SortChips";
import SortPanel from "./SortPanel";
import SortMenu, { defaultSortKey } from "./SortMenu";
import { sortAdd, sortHeaderClick, sortOnly, sortRemove } from "./tableSort";
import type { RowActions, RowsHandle, ServerSortProps, SortSpec } from "./GridView";

const SUBS: { key: TableSub; label: string }[] = [
  { key: "data", label: "Data" },
  { key: "structure", label: "Structure" },
  { key: "ddl", label: "DDL" },
];

const OPS: { op: FilterOp; label: string }[] = [
  { op: "eq", label: "=" },
  { op: "ne", label: "≠" },
  { op: "lt", label: "<" },
  { op: "le", label: "≤" },
  { op: "gt", label: ">" },
  { op: "ge", label: "≥" },
  { op: "like", label: "LIKE" },
  { op: "not_like", label: "NOT LIKE" },
  { op: "is_null", label: "IS NULL" },
  { op: "is_not_null", label: "IS NOT NULL" },
];

function needsValue(op: FilterOp): boolean {
  return op !== "is_null" && op !== "is_not_null";
}

type HeaderMenu = { column: string; x: number; y: number };

/// Save of the pending changes in the dialog: preview ("View SQL", in
/// confirm) or outcome to show (error, rows ≠ 1). `sql` is the preview
/// generated by the backend from the SAME parameters it then executes.
type BatchState = {
  /// UPDATEs of the cells and INSERTs of the new rows, in execution order.
  writes: TableWrite[];
  sql: string;
  /// Changed cells + new rows (the unchanged ones are skipped).
  cells: number;
  phase: "confirm" | "running" | "done";
  result: BatchUpdateOut | null;
  /// Command refused (lane busy, validation): no outcome.
  error: ErrorOut | null;
  /// Saved rows already re-read in the grid: no reload on close.
  refreshed?: boolean;
};

export default function TableTab({
  tab,
  gridHost,
  gridSize,
}: {
  tab: TabUi;
  gridHost: React.RefObject<HTMLDivElement>;
  gridSize: { w: number; h: number };
}) {
  // M3.5: the tab is tied to ITS connection; null connId = disconnected.
  const connId = tab.connId;
  // The shared one is one per connection (§3.1): one load at a time. The
  // other tabs of the same connection wait — the effect restarts by itself.
  const busy = useStore((s) => (connId !== null ? sharedBusyTab(s, connId) : undefined));
  const table = tab.table!;
  const loaded = tab.statements[0];
  // Data kept on screen during a re-query (see `keepOnScreen`): shown until
  // the new load has rows or an outcome.
  // Lives in a ref, not in state: the tab store updates synchronously and
  // the render that sees the data already removed must also see the kept
  // data (with useState they came in two renders: a flash of "loading…").
  // `bump` only serves to redraw.
  const staleRef = useRef<{ st: StatementUi; connId: number } | null>(null);
  const [, bump] = useState(0);
  const stale = staleRef.current;
  const fresh = loaded !== undefined && (loaded.rows > 0 || loaded.outcome !== null);
  const showingStale = stale !== null && !fresh;
  const st = showingStale ? stale.st : loaded;
  const tq = tab.tableQuery;
  const [menu, setMenu] = useState<HeaderMenu | null>(null);
  // Filter just added from the menu: stays a draft (no re-query) until the
  // user confirms a value or an operator without an operand.
  const [draft, setDraft] = useState<ColumnFilter | null>(null);
  // Local sort (downloaded rows only): now requested from the header menu,
  // the click sorts on the server. The real state lives in GridView; here
  // the request and the mirror for the menu.
  const [localSort, setLocalSort] = useState<SortSpec | null>(null);
  const [localReq, setLocalReq] = useState<ServerSortProps["localRequest"]>(null);
  // WHERE bar: text being typed, applied only with Enter. Realigned when the
  // query changes from outside (Back/Forward, reset).
  const [whereDraft, setWhereDraft] = useState(tq.where_sql);
  useEffect(() => setWhereDraft(tq.where_sql), [tq.where_sql]);
  // Editing: the edited cells stay pending (tab.pending) until saving; the
  // dialog is only for "View SQL" and for the outcomes.
  const [batch, setBatch] = useState<BatchState | null>(null);
  const [saving, setSaving] = useState(false);
  const conn = useStore((s) => (connId !== null ? connById(s, connId) : undefined));

  // PK from introspection (same query key as the tree and Structure):
  // decides whether the grid is editable (decision 6: without a PK,
  // read-only) and which columns make up the WHERE of the UPDATE.
  const cols = useQuery({
    queryKey: ["columns", connId, table.schema, table.name],
    queryFn: () => ipc.schemaColumns(connId!, table.schema, table.name),
    staleTime: Infinity,
    enabled: connId !== null,
  });
  const pkCols = (cols.data ?? []).filter((c) => c.is_primary_key).map((c) => c.name);
  // §9.7 point 4: in read-only mode editing does not start at all — the
  // backend would refuse anyway, but the overlay must not even open.
  const readOnly = conn?.profile.read_only ?? false;

  // The key serializes the query: it changes → the effect reloads even if a
  // previous attempt had failed with empty statements.
  const queryKey = JSON.stringify(tq);
  // Tab just opened: first the saved default sort (step 5), then the load
  // — a single query, already sorted. Columns that no longer exist are
  // skipped. Any error: load without.
  const qc = useQueryClient();
  const profileId = tab.profileId ?? conn?.profile.id ?? null;
  useEffect(() => {
    if (!tab.applyDefaultSort || connId === null) return;
    let alive = true;
    void (async () => {
      let order: OrderBy[] | null = null;
      try {
        if (profileId !== null) {
          const { schema, name } = table;
          const [def, columns] = await Promise.all([
            qc.fetchQuery({
              queryKey: defaultSortKey(profileId, schema, name),
              queryFn: () => ipc.tableDefaultSortGet(profileId, schema, name),
              staleTime: Infinity,
            }),
            qc.fetchQuery({
              queryKey: ["columns", connId, schema, name],
              queryFn: () => ipc.schemaColumns(connId, schema, name),
              staleTime: Infinity,
            }),
          ]);
          if (def) {
            const known = new Set(columns.map((c) => c.name));
            order = def.filter((o) => known.has(o.column));
          }
        }
      } catch (e) {
        console.error(e);
      }
      if (!alive) return;
      useStore.getState().resolveDefaultSort(tab.id, order);
      if (order && order.length > 0) persistWorkspace();
    })();
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab.applyDefaultSort, connId, profileId, table.schema, table.name]);

  const needLoad = connId !== null && !busy && tab.statements.length === 0 && !tab.applyDefaultSort;
  // Load refused before starting (e.g. WHERE written with a `;`): shown in
  // place of "loading…". `attempt` restarts the effect with Reload even if
  // nothing else changed.
  const [loadError, setLoadError] = useState<ErrorOut | null>(null);
  const [attempt, setAttempt] = useState(0);
  // Start of a load still waiting for its connection (checking it, or
  // opening it behind SSH): set only after a second, so a quick load
  // keeps the plain "loading…".
  const [connectingSince, setConnectingSince] = useState<number | null>(null);
  useEffect(() => {
    if (!needLoad || connId === null) return;
    setLoadError(null);
    const started = Date.now();
    const slow = window.setTimeout(() => setConnectingSince(started), 1000);
    void (async () => {
      try {
        const execId = await ipc.tableData(connId, table.schema, table.name, tq, (ev) =>
          useStore.getState().handleEvent(connId, ev)
        );
        useStore.getState().startExecution(tab.id, execId, "shared");
      } catch (e) {
        console.error(e);
        setLoadError(asErrorOut(e));
      } finally {
        window.clearTimeout(slow);
        setConnectingSince(null);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [needLoad, connId, tab.id, table.schema, table.name, queryKey, attempt]);

  // Closing the context menu: same convention as TabBar (mousedown outside).
  useEffect(() => {
    if (!menu) return;
    const close = () => setMenu(null);
    window.addEventListener("mousedown", close);
    window.addEventListener("blur", close);
    return () => {
      window.removeEventListener("mousedown", close);
      window.removeEventListener("blur", close);
    };
  }, [menu]);

  const releaseResults = () => releaseTabResults(tab);
  const cancelLoad = () => {
    if (connId !== null && tab.execId !== null) void ipc.cancel(connId, tab.execId);
  };

  // Re-query on the same table (sort, filters, Reload): as in DBeaver the
  // data stays on screen until the new data arrives, then it is replaced —
  // no grid disappearing and reappearing. The old result set is released
  // only then (the grid is still reading it).
  const releaseStale = () => {
    const s = staleRef.current;
    if (!s) return;
    if (s.st.resultId !== null) {
      void ipc.releaseResult(s.connId, s.st.resultId);
      dropCache(s.connId, s.st.resultId);
    }
    staleRef.current = null;
    bump((n) => n + 1);
  };
  /// In place of `releaseResults` before a re-query: keeps the current data
  /// on screen. If some is already kept (two re-queries in a row), only the
  /// load in progress is released.
  const keepOnScreen = () => {
    const cur = tab.statements[0];
    if (staleRef.current || connId === null || !cur || cur.resultId === null || cur.rows === 0) {
      releaseResults();
      return;
    }
    staleRef.current = { st: cur, connId };
    bump((n) => n + 1);
  };
  // New data arrived (or an error, or the connection closed): the old data
  // goes. Tab unmounted (another tab active) mid-switch: same.
  useEffect(() => {
    // Never the result that is still the loaded one (same id): it would be
    // on screen and released from under the grid.
    if (!stale || stale.st.resultId === loaded?.resultId) return;
    if (fresh || loadError !== null || connId === null) releaseStale();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stale, fresh, loadError, connId, loaded?.resultId]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => () => releaseStale(), []);

  const clearStatements = () =>
    useStore.setState((prev) => ({
      tabs: prev.tabs.map((t) =>
        t.id === tab.id ? { ...t, statements: [], execId: null, execState: "idle" } : t
      ),
    }));

  const reload = (keep = false) => {
    if (keep) keepOnScreen();
    else releaseResults();
    // Emptying the statements already restarts the load (`needLoad`);
    // `attempt` only when they were empty (failed load). Both at once
    // started it twice, and the second was refused as "already loading".
    const empty = tab.statements.length === 0;
    clearStatements();
    if (empty) setAttempt((a) => a + 1);
  };

  // Writes of the transaction undone (§9.7): the grid may show values
  // saved inside it — re-read, unless there are unsaved changes (the
  // user's Reload asks about them).
  const undone = conn?.undone ?? 0;
  const seenUndone = useRef(undone);
  useEffect(() => {
    if (undone === seenUndone.current) return;
    seenUndone.current = undone;
    if (nUnsaved === 0) reload(true);
  }, [undone]);

  /// Reload requested by the user (button, F5): with pending changes first
  /// the Save / Discard / Cancel question. The data stays on screen until
  /// the new data arrives.
  const userReload = async () => {
    if (!(await guardUnsaved([tab.id]))) return;
    reload(true);
  };

  /// Applies a new server-side query: releases the results and reloads.
  const applyQuery = async (next: TableQuery) => {
    if (tab.running) return;
    if (!(await guardUnsaved([tab.id]))) return;
    keepOnScreen();
    useStore.getState().setTableQuery(tab.id, next);
    clearStatements();
    persistWorkspace();
  };

  // ------------------------------------------------- next pages
  // At the bottom the next page is appended to the same result set:
  // selection, widths and position stay. Reads the fresh state from the
  // store: the scroll calls several times in a row, only one must start.
  const loadMore = (retry = false) => {
    const s = useStore.getState();
    const cur = s.tabs.find((x) => x.id === tab.id);
    const cst = cur?.statements[0];
    if (!cur || !cst || cst.resultId === null || connId === null || !cur.table) return;
    if (cur.running || !tableMayHaveMore(cur) || sharedBusyTab(s, connId)) return;
    if (!retry && cur.more?.resultId === cst.resultId && cur.more.error) return;
    const resultId = cst.resultId;
    s.tableMoreStart(cur.id, resultId);
    ipc
      .tableDataMore(connId, cur.table.schema, cur.table.name, cur.tableQuery, resultId)
      .then((out) => useStore.getState().tableMoreEnd(cur.id, resultId, out, null))
      .catch((e) => useStore.getState().tableMoreEnd(cur.id, resultId, null, asErrorOut(e)));
  };
  const more = st && tab.more?.resultId === st.resultId ? tab.more : null;

  // ------------------------------------------- navigation by foreign keys
  // (interface plan, step 7). From introspection, in both directions:
  // outgoing (this row → parent record) and incoming (child rows pointing
  // to this row). Navigation happens INSIDE the tab, with back/forward.
  const fks = useQuery({
    queryKey: ["fks", connId, table.schema, table.name],
    queryFn: () => ipc.schemaForeignKeys(connId!, table.schema, table.name),
    staleTime: Infinity,
    enabled: connId !== null,
  });
  const isHere = (schema: string, name: string) => schema === table.schema && name === table.name;
  const outgoing = (fks.data ?? []).filter((f) => isHere(f.schema, f.table));
  const incoming = (fks.data ?? []).filter((f) => isHere(f.ref_schema, f.ref_table));

  // Table changed inside the tab: drafts and confirmations of the previous one go.
  useEffect(() => {
    setDraft(null);
    setBatch(null);
    setMenu(null);
  }, [table.schema, table.name]);

  /// Values of the row for those columns. `null` if one is missing, is NULL
  /// (a NULL key points to nothing) or is truncated (it would filter on the piece).
  const rowValues = (row: number, names: string[]): string[] | null => {
    const stc = st?.columns;
    if (!stc || st.resultId === null || connId === null) return null;
    const cache = cacheFor(connId, st.resultId, stc.length);
    const out: string[] = [];
    for (const name of names) {
      const cell = cache.cell(row, stc.findIndex((c) => c.name === name));
      if (cell === undefined || cell.isNull || cell.truncated) return null;
      out.push(cell.v);
    }
    return out;
  };

  /// Opens `target` filtered by `columns = values`: in the same tab (with
  /// the current stop in the history) or in a new tab.
  const goTo = async (target: TableRef, columns: string[], values: string[], newTab: boolean) => {
    if (connId === null) return;
    const query: TableQuery = {
      ...emptyTableQuery(),
      filters: columns.map((column, i) => ({ column, op: "eq" as FilterOp, value: values[i] })),
    };
    if (newTab) {
      const id = newTableTab(connId, target.schema, target.name);
      useStore.getState().setTableQuery(id, query);
      persistWorkspace();
      return;
    }
    if (tab.running) return;
    if (!(await guardUnsaved([tab.id]))) return;
    releaseResults();
    useStore.getState().navigateTable(tab.id, target, query);
    persistWorkspace();
  };

  const navStep = async (dir: -1 | 1) => {
    if (tab.running || (dir < 0 ? tab.navBack : tab.navFwd).length === 0) return;
    if (!(await guardUnsaved([tab.id]))) return;
    releaseResults();
    useStore.getState().navStep(tab.id, dir);
    persistWorkspace();
  };

  const relName = (schema: string, name: string) => (schema === table.schema ? name : `${schema}.${name}`);
  const eqText = (cols: string[], vals: string[]) => cols.map((c, i) => `${c} = ${vals[i]}`).join(", ");
  const parentOf = (f: ForeignKeyOut): TableRef => ({ schema: f.ref_schema, name: f.ref_table });

  /// Cell menu on a column with a foreign key: go to the parent record.
  const cellActions = (row: number, col: number) => {
    const name = st?.columns?.[col]?.name;
    if (!name) return [];
    return outgoing
      .filter((f) => f.columns.includes(name))
      .flatMap((f) => {
        const vals = rowValues(row, f.columns);
        if (!vals) return [];
        const what = `${relName(f.ref_schema, f.ref_table)} (${eqText(f.ref_columns, vals)})`;
        return [
          { label: t("Open {what}", { what: what }), onClick: () => goTo(parentOf(f), f.ref_columns, vals, false) },
          { label: t("… in a new tab"), onClick: () => goTo(parentOf(f), f.ref_columns, vals, true) },
        ];
      });
  };

  /// Columns with an outgoing foreign key → the columns of the key, drawn as
  /// links in the grid. Memo: a new map redraws the whole grid.
  const resultCols = st?.columns;
  const linkCols = useMemo(() => {
    if (!resultCols) return undefined;
    const map = new Map<number, number[]>();
    for (const f of outgoing) {
      const key = f.columns.map((c) => resultCols.findIndex((rc) => rc.name === c));
      if (key.some((k) => k < 0)) continue;
      for (const k of key) if (!map.has(k)) map.set(k, key);
    }
    return map.size > 0 ? map : undefined;
    // `outgoing` is derived from fks.data at every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fks.data, resultCols, table.schema, table.name]);

  /// Click on the link arrow of a cell: the first foreign key of the column,
  /// like the row card.
  const followLink = (row: number, col: number, newTab: boolean) => {
    const name = st?.columns?.[col]?.name;
    const f = outgoing.find((fk) => name !== undefined && fk.columns.includes(name));
    const vals = f && rowValues(row, f.columns);
    if (f && vals) void goTo(parentOf(f), f.ref_columns, vals, newTab);
  };

  /// Links for the row card: link fields and child tables.
  const rowLinks = (row: number): RowLinks => {
    const fields: RowLinks["fields"] = {};
    for (const f of outgoing) {
      const vals = rowValues(row, f.columns);
      if (!vals) continue;
      const link = {
        label: relName(f.ref_schema, f.ref_table),
        title: `${relName(f.ref_schema, f.ref_table)}: ${eqText(f.ref_columns, vals)}`,
        go: (newTab: boolean) => goTo(parentOf(f), f.ref_columns, vals, newTab),
      };
      for (const c of f.columns) fields[c] ??= link;
    }
    const related = incoming.flatMap((f) => {
      const vals = rowValues(row, f.ref_columns);
      if (!vals) return [];
      return [
        {
          label: `${relName(f.schema, f.table)} (${f.columns.join(", ")})`,
          title: `${relName(f.schema, f.table)}: ${eqText(f.columns, vals)}`,
          go: (newTab: boolean) => goTo({ schema: f.schema, name: f.table }, f.columns, vals, newTab),
        },
      ];
    });
    return { fields, related };
  };

  // ⌥← / ⌥→: back/forward in the tab, like in the browser. Not inside text
  // fields, where ⌥+arrow moves the cursor by one word.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (!e.altKey || e.metaKey || e.ctrlKey || (e.key !== "ArrowLeft" && e.key !== "ArrowRight")) return;
      const el = e.target as HTMLElement | null;
      if (el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName))) return;
      e.preventDefault();
      navStep(e.key === "ArrowLeft" ? -1 : 1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab.id, tab.running, tab.navBack.length, tab.navFwd.length]);

  /// PK key of the row, with the current values from the cache. PK truncated
  /// in the window (>4KB): the full value via getCellFull. `null` = cell not
  /// in cache (rare race: the block is requested, the user retries).
  const rowKey = async (row: number): Promise<CellAssign[] | null> => {
    const stc = st?.columns;
    if (!stc || st.resultId === null || connId === null) return null;
    const cache = cacheFor(connId, st.resultId, stc.length);
    const key: CellAssign[] = [];
    for (const pk of pkCols) {
      const idx = stc.findIndex((c) => c.name === pk);
      if (idx < 0) return null;
      const cell = cache.cell(row, idx);
      if (cell === undefined) {
        cache.request(row);
        return null;
      }
      const v = cell.truncated
        ? await ipc.getCellFull(connId, st.resultId, row, idx)
        : cell.isNull
          ? null
          : cell.v;
      key.push({ column: pk, value: v });
    }
    return key;
  };

  const cols_nullable = (column: string) =>
    cols.data?.find((c) => c.name === column)?.nullable ?? true;

  const pending = tab.pending;
  // New rows ("+ Row"): row `st.rows + i` for the grid's callbacks, on
  // screen below the row they were added under (`NewRow.after`).
  const newRows = tab.newRows;
  const nNew = newRows.length;
  // Rows to delete (Delete key / "Delete"): by PK id.
  const deleted = tab.deleted;
  const nDeleted = Object.keys(deleted).length;
  const nUnsaved = unsavedCount(tab);
  // Edited cells that Save writes (not those of the rows to delete).
  const nPending = nUnsaved - nNew - nDeleted;
  // Rows touched by the grid selection: target of Duplicate/Delete.
  const [selRows, setSelRows] = useState<number[]>([]);
  const [focusCell, setFocusCell] = useState<{ col: number; row: number; nonce: number } | undefined>();

  /// Puts the cells in pending. A cell brought back to the read value leaves
  /// pending; NULL on a NOT NULL column is skipped (introspection). All or
  /// nothing: a block not in cache is requested and the edit dropped — the
  /// changes would end up on rows other than the ones shown.
  // One stage at a time, in order: the cell panel stages at every
  // keystroke and a stage awaits (row key, full value) — an older one
  // finishing later would put back an older text.
  const stageChain = useRef<Promise<void>>(Promise.resolve());
  const stage = (cells: { row: number; col: number; value: PendingValue }[]): Promise<void> => {
    const run = stageChain.current.then(() => stageNow(cells));
    stageChain.current = run.catch(() => {});
    return run;
  };
  const stageNow = async (cells: { row: number; col: number; value: PendingValue }[]) => {
    if (batch || saving || connId === null || tab.running || readOnly) return;
    const stc = st?.columns;
    if (!stc || st.resultId === null || pkCols.length === 0) return;
    // Cells of the new rows: they change the pending row, no UPDATE.
    const onNew = cells.filter((c) => c.row >= st.rows);
    if (onNew.length > 0) {
      const s = useStore.getState();
      const rows = [...(s.tabs.find((x) => x.id === tab.id)?.newRows ?? [])];
      for (const { row, col, value } of onNew) {
        const column = stc[col]?.name;
        const i = row - st.rows;
        if (!column || !rows[i]) continue;
        if (value === null && !cols_nullable(column)) continue;
        rows[i] = { ...rows[i], values: { ...rows[i].values, [column]: value } };
      }
      s.setNewRows(tab.id, rows);
      cells = cells.filter((c) => c.row < st.rows);
      if (cells.length === 0) return;
    }
    const cache = cacheFor(connId, st.resultId, stc.length);
    // A whole column covers rows never scrolled to: their blocks first.
    const first = cells.reduce((m, c) => Math.min(m, c.row), Infinity);
    const last = cells.reduce((m, c) => Math.max(m, c.row), -1);
    await cache.ensure(first, last + 1);
    const keys = new Map<number, CellAssign[]>();
    const changes: { key: CellAssign[]; column: string; value: PendingValue; same: boolean }[] = [];
    for (const { row, col, value } of cells) {
      const column = stc[col]?.name;
      if (!column) continue;
      const cur = cache.cell(row, col);
      if (cur === undefined) {
        cache.request(row);
        return;
      }
      if (value === null && !cols_nullable(column)) continue;
      // Truncated: compared with the full value (the cell panel edits it
      // and its Esc writes it back), read only when the piece matches.
      // DEFAULT is never "equal": the server decides the value.
      const same =
        isDefaultCell(value)
          ? false
          : value === null
            ? cur.isNull
            : cur.isNull
              ? false
              : !cur.truncated
                ? value === cur.v
                : value.startsWith(cur.v) &&
                  value === (await ipc.getCellFull(connId, st.resultId, row, col).catch(() => null));
      let key = keys.get(row);
      if (!key) {
        const k = await rowKey(row);
        if (!k) return;
        keys.set(row, k);
        key = k;
      }
      changes.push({ key, column, value, same });
    }
    if (changes.length === 0) return;
    // Fresh state: rowKey is async, it may have changed in the meantime.
    const s = useStore.getState();
    const next: PendingEdits = { ...(s.tabs.find((x) => x.id === tab.id)?.pending ?? {}) };
    for (const ch of changes) {
      const id = pendingRowId(ch.key.map((k) => k.value));
      const row = next[id] ? { key: next[id].key, set: { ...next[id].set } } : { key: ch.key, set: {} };
      if (ch.same) delete row.set[ch.column];
      else row.set[ch.column] = ch.value;
      if (Object.keys(row.set).length > 0) next[id] = row;
      else delete next[id];
    }
    s.setPending(tab.id, next);
    // Preview tab: with changes it becomes permanent, otherwise the next
    // click in the tree would replace it, taking the changes away.
    if (s.tabs.find((x) => x.id === tab.id)?.preview) makePermanent(tab.id);
  };

  /// Pending value of the cell, for the grid. Finds the row from the PK
  /// values in cache (truncated PK = no highlight, edge case).
  const pkKey = pkCols.join("\u0000");
  const pendingAt = useMemo(() => {
    const stc = st?.columns;
    if (!stc || !st || st.resultId === null || connId === null) return undefined;
    if (Object.keys(pending).length === 0) return undefined;
    const idx = pkCols.map((n) => stc.findIndex((c) => c.name === n));
    if (idx.length === 0 || idx.some((i) => i < 0)) return undefined;
    const cache = cacheFor(connId, st.resultId, stc.length);
    return (row: number, col: number): PendingValue | undefined => {
      const vals: (string | null)[] = [];
      for (const i of idx) {
        const cell = cache.cell(row, i);
        if (cell === undefined || cell.truncated) return undefined;
        vals.push(cell.isNull ? null : cell.v);
      }
      const pr = pending[pendingRowId(vals)];
      const name = stc[col]?.name;
      if (!pr || name === undefined || !Object.prototype.hasOwnProperty.call(pr.set, name)) return undefined;
      return pr.set[name];
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pending, st?.columns, st?.resultId, connId, pkKey]);

  const pendingWrites = (): TableWrite[] =>
    pendingToWrites({ pending, newRows, deleted }, numericColumns(st?.columns));
  const settle = (writes: TableWrite[], result: BatchUpdateOut) => {
    if (connId !== null) settleWrites(tab.id, connId, writes, result);
  };

  /// Where the backend appends the inserted rows: the open result set, with
  /// the PK to re-read them where there is no RETURNING, and `at`, the
  /// screen row of each one (see `rowLayout`) so it stays there — not with
  /// the local sort, which sorts them anyway.
  const appendTo = (): AppendTo | null =>
    st?.resultId !== null && st?.resultId !== undefined
      ? {
          result_id: st.resultId,
          key_columns: pkCols,
          at: localSort ? [] : newRows.map((r, i) => Math.min(Math.max(r.after, -1), st.rows - 1) + 1 + i),
        }
      : null;

  /// After a clean save updates the grid in place, without reloading the
  /// table (scroll, selection and pages stay): the edited rows are re-read
  /// from the database, the inserted ones were already appended by the
  /// backend (`appended`) and here the count is extended.
  /// `false` = it did not work (row not found, inserted row not re-read,
  /// error): reload.
  const refreshSaved = async (writes: TableWrite[], result: BatchUpdateOut): Promise<boolean> => {
    const resultId = st?.resultId;
    const stc = st?.columns;
    if (connId === null || resultId === null || resultId === undefined || !stc) return false;
    const inserts = writes.filter((w) => w.kind === "insert").length;
    const deletes = writes.filter((w) => w.kind === "delete").length;
    if (result.appended !== inserts || result.removed !== deletes) return false;
    if (deletes > 0 || inserts > 0) {
      // Rows removed from the view or inserted in the middle: everything
      // below shifts, the loaded blocks are re-read (the old stays on
      // screen until the new arrives).
      await cacheFor(connId, resultId, stc.length).refreshLoaded();
    }
    if (inserts > 0 || deletes > 0)
      useStore.getState().setStatementRows(tab.id, resultId, result.rows ?? st.rows + inserts - deletes);
    const updates: RowUpdate[] = writes.flatMap((w) => (w.kind === "update" ? [w] : []));
    if (updates.length === 0) return true;
    try {
      const out = await ipc.tableRefreshRows(connId, table.schema, table.name, resultId, updates);
      if (out.missing > 0) return false;
      await cacheFor(connId, resultId, stc.length).refreshLoaded();
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  };

  const isClean = (r: BatchUpdateOut) => !r.error && r.applied.every((n) => n === 1);

  /// After a save that moved rows (deleted ones gone, new ones real): the
  /// cursor back on its row. `cursor` read before the save, while the rows
  /// to delete were still on screen. With the local sort the grid re-sorts.
  const keepCursor = (cursor: readonly [number, number] | null, writes: TableWrite[]) => {
    if (!cursor || localSort || writes.every((w) => w.kind === "update")) return;
    setFocusCell({ col: cursor[0], row: cursor[1], nonce: Date.now() });
  };

  /// Save (Cmd+S): one UPDATE per row, atomic on the shared connection, no
  /// dialog. The dialog appears only if there is something to say: error or
  /// affected rows ≠ 1.
  const save = async () => {
    if (batch || saving || connId === null || tab.running || readOnly || nUnsaved === 0) return;
    const writes = pendingWrites();
    const cursor = gridRows.current?.cursorAfterSave() ?? null;
    setSaving(true);
    try {
      const result = await ipc.tableWriteBatch(connId, table.schema, table.name, writes, appendTo());
      if (isClean(result)) {
        // First the new values in the grid, then the highlight goes: the
        // other way round the old values would show for an instant.
        const ok = await refreshSaved(writes, result);
        settle(writes, result);
        if (ok) keepCursor(cursor, writes);
        else reload();
        return;
      }
      settle(writes, result);
      const sql = await ipc
        .tableWriteSqlBatch(connId, table.schema, table.name, writes)
        .catch(() => "");
      setBatch({ writes, sql, cells: nUnsaved, phase: "done", result, error: null });
    } catch (e) {
      // Command refused (lane busy, validation): nothing started. Shown in
      // the dialog, from where it can be retried.
      const sql = await ipc
        .tableWriteSqlBatch(connId, table.schema, table.name, writes)
        .catch(() => "");
      setBatch({ writes, sql, cells: nUnsaved, phase: "confirm", result: null, error: asErrorOut(e) });
    } finally {
      setSaving(false);
    }
  };
  // Cmd+S from the global listener: always the version of this render.
  const saveRef = useRef(save);
  saveRef.current = save;
  useEffect(() => {
    if (tab.sub !== "data") return;
    const onKey = (e: KeyboardEvent) => {
      if (!(e.metaKey || e.ctrlKey) || e.altKey || e.shiftKey || e.key.toLowerCase() !== "s") return;
      e.preventDefault();
      void saveRef.current();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [tab.sub]);

  // ⌘F goes to the WHERE, ⇧⌘F opens "+ Filter": the bar without the mouse.
  // The text search (Studio's ⌘F) applies only to the SQL tabs.
  const whereRef = useRef<WhereInputHandle | null>(null);
  const filterAddRef = useRef<FilterAddHandle | null>(null);
  useEffect(() => {
    if (tab.sub !== "data") return;
    const onKey = (e: KeyboardEvent) => {
      if (!(e.metaKey || e.ctrlKey) || e.altKey || e.key.toLowerCase() !== "f" || e.defaultPrevented) return;
      e.preventDefault();
      if (e.shiftKey) filterAddRef.current?.open();
      else whereRef.current?.focus();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [tab.sub]);

  // Structure and DDL stay in cache (infinite staleTime): a column added by
  // a query does not appear by itself. The ⟳ (or F5) re-reads both from the
  // server; columns and PK are the same as the tree's and Data's, which
  // update together. The ones on screen stay until the new ones arrive.
  const metaKeys = [
    ["columns", connId, table.schema, table.name],
    ["ddl", connId, table.schema, table.name],
  ];
  const metaFetching =
    useIsFetching({ queryKey: metaKeys[0], exact: true }) + useIsFetching({ queryKey: metaKeys[1], exact: true }) > 0;
  const reloadMeta = () => {
    for (const queryKey of metaKeys) void qc.invalidateQueries({ queryKey, exact: true });
  };

  // F5 / Cmd+R: in Data reloads the data with the same query (filters and
  // server sort stay), like the button. The pending changes stay: they are
  // tied to the PK, not to the row. In Structure and DDL re-reads the table
  // definition.
  const refreshRef = useRef(() => {});
  refreshRef.current = () => {
    if (connId === null) return;
    if (tab.sub !== "data") {
      if (!metaFetching) reloadMeta();
      return;
    }
    if (tab.running || saving) return;
    void userReload();
  };
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const cmdR = (e.metaKey || e.ctrlKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === "r";
      if (e.key !== "F5" && !cmdR) return;
      // Always blocked: in the webview F5/Cmd+R would reload the app.
      e.preventDefault();
      refreshRef.current();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  /// "View SQL": the UPDATEs and INSERTs that Save would run, in the
  /// confirmation dialog.
  const preview = async () => {
    if (batch || saving || connId === null || nUnsaved === 0) return;
    const writes = pendingWrites();
    try {
      const sql = await ipc.tableWriteSqlBatch(connId, table.schema, table.name, writes);
      setBatch({ writes, sql, cells: nUnsaved, phase: "confirm", result: null, error: null });
    } catch (e) {
      console.error(e);
    }
  };

  const discard = () => {
    useStore.getState().setPending(tab.id, {});
    useStore.getState().setNewRows(tab.id, []);
    useStore.getState().setDeleted(tab.id, {});
  };

  /// Rows can be added, duplicated and deleted: editable table with a key,
  /// nothing running or being saved.
  const canEditRows = () =>
    !batch && !saving && connId !== null && !tab.running && !readOnly && pkCols.length > 0 && !!st?.columns;

  /// The grid's rows: where new rows go (below the selection, like
  /// DBeaver) and where the cursor lands after a save.
  const gridRows = useRef<RowsHandle | null>(null);

  /// Inserts new rows at the grid's slot and moves the focus to the first
  /// of them. With changes the preview tab becomes permanent (like `stage`).
  const pushNewRows = (added: Record<string, PendingValue>[]) => {
    if (added.length === 0 || !st) return;
    const s = useStore.getState();
    const rows = [...(s.tabs.find((x) => x.id === tab.id)?.newRows ?? [])];
    const slot = gridRows.current?.slot() ?? { after: st.rows - 1, index: rows.length };
    rows.splice(slot.index, 0, ...added.map((values) => ({ id: crypto.randomUUID(), after: slot.after, values })));
    s.setNewRows(tab.id, rows);
    if (s.tabs.find((x) => x.id === tab.id)?.preview) makePermanent(tab.id);
    setFocusCell({ col: 0, row: st.rows + slot.index, nonce: Date.now() });
  };

  const isPk = (column: string) => cols.data?.find((x) => x.name === column)?.is_primary_key ?? false;

  /// "+ Row" (⌥Insert, like DBeaver): a new row below the selected one, to
  /// fill in; it becomes an INSERT with Save. Starts with DEFAULT where
  /// the server knows what to put (declared default, PK/identity) and NULL
  /// elsewhere.
  const addRow = () => {
    if (!canEditRows()) return;
    const values: Record<string, PendingValue> = {};
    for (const c of st!.columns!) {
      const info = cols.data?.find((x) => x.name === c.name);
      values[c.name] = info && (info.default !== null || info.is_primary_key) ? DEFAULT_CELL : null;
    }
    pushNewRows([values]);
  };

  /// "Duplicate" (⌃⌥Insert, like DBeaver): copies of the selected rows
  /// below them, with the values as seen (pending changes
  /// included) and the PK at DEFAULT, otherwise the INSERT would repeat the key.
  const duplicateRows = async (rows: number[]) => {
    if (!canEditRows() || rows.length === 0) return;
    const stc = st!.columns!;
    const resultId = st!.resultId;
    if (resultId === null) return;
    const cache = cacheFor(connId!, resultId, stc.length);
    const added: Record<string, PendingValue>[] = [];
    for (const row of rows) {
      const values: Record<string, PendingValue> = {};
      if (row >= st!.rows) {
        const src = newRows[row - st!.rows];
        if (!src) continue;
        for (const c of stc) values[c.name] = isPk(c.name) ? DEFAULT_CELL : (src.values[c.name] ?? null);
        added.push(values);
        continue;
      }
      for (let col = 0; col < stc.length; col++) {
        const name = stc[col].name;
        if (isPk(name)) {
          values[name] = DEFAULT_CELL;
          continue;
        }
        const p = pendingAt?.(row, col);
        if (p !== undefined) {
          values[name] = p;
          continue;
        }
        // Not in cache or truncated (LOB): the full value from the backend.
        const cell = cache.cell(row, col);
        values[name] =
          cell === undefined || cell.truncated
            ? await ipc.getCellFull(connId!, resultId, row, col)
            : cell.isNull
              ? null
              : cell.v;
      }
      added.push(values);
    }
    pushNewRows(added);
  };

  /// "Delete" (Delete key, like DBeaver): the real rows are marked for
  /// deletion (red and struck through, DELETE with Save); the unsaved new
  /// rows disappear right away. If they are all already marked, restores them.
  const deleteRows = async (rows: number[]) => {
    if (!canEditRows() || rows.length === 0) return;
    const base = st!.rows;
    const s0 = useStore.getState().tabs.find((x) => x.id === tab.id);
    if (!s0) return;
    const fresh = rows.filter((r) => r >= base).map((r) => r - base);
    if (fresh.length > 0) {
      const gone = new Set(fresh);
      useStore.getState().setNewRows(tab.id, s0.newRows.filter((_, i) => !gone.has(i)));
    }
    const real = rows.filter((r) => r < base);
    if (real.length === 0) return;
    const keys: CellAssign[][] = [];
    for (const row of real) {
      const k = await rowKey(row);
      // Row not yet in cache: it was requested, the user retries.
      if (!k) return;
      keys.push(k);
    }
    const s = useStore.getState();
    const cur = { ...(s.tabs.find((x) => x.id === tab.id)?.deleted ?? {}) };
    const ids = keys.map((k) => pendingRowId(k.map((a) => a.value)));
    const restore = ids.every((id) => id in cur);
    keys.forEach((k, i) => {
      if (restore) delete cur[ids[i]];
      else cur[ids[i]] = k;
    });
    s.setDeleted(tab.id, cur);
    if (s.tabs.find((x) => x.id === tab.id)?.preview) makePermanent(tab.id);
  };

  /// Real row marked for deletion, for the grid (same lookup by PK as
  /// `pendingAt`).
  const deletedAt = useMemo(() => {
    const stc = st?.columns;
    if (!stc || !st || st.resultId === null || connId === null || nDeleted === 0) return undefined;
    const idx = pkCols.map((n) => stc.findIndex((c) => c.name === n));
    if (idx.length === 0 || idx.some((i) => i < 0)) return undefined;
    const cache = cacheFor(connId, st.resultId, stc.length);
    return (row: number): boolean => {
      const vals: (string | null)[] = [];
      for (const i of idx) {
        const cell = cache.cell(row, i);
        if (cell === undefined || cell.truncated) return false;
        vals.push(cell.isNull ? null : cell.v);
      }
      return pendingRowId(vals) in deleted;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [deleted, nDeleted, st?.columns, st?.resultId, connId, pkKey]);

  const rowActions: RowActions | undefined =
    pkCols.length > 0 && !readOnly
      ? {
          onAdd: addRow,
          onDuplicate: (rows) => void duplicateRows(rows),
          onDelete: (rows) => void deleteRows(rows),
          deletedAt,
          onSelectedRows: setSelRows,
          handleRef: gridRows,
        }
      : undefined;
  // Delete button: becomes "Restore" if the selected real rows are all
  // already marked for deletion.
  const selAllDeleted =
    st !== undefined &&
    selRows.length > 0 &&
    selRows.every((r) => r < st.rows && deletedAt?.(r) === true);

  /// The new rows for the grid (see GridView.extraRows). New identity at
  /// every change: the grid redraws.
  const extraRows = useMemo(
    () =>
      nNew === 0
        ? undefined
        : {
            after: newRows.map((r) => r.after),
            cell: (i: number, col: number): PendingValue => {
              const name = st?.columns?.[col]?.name;
              const r: NewRow | undefined = newRows[i];
              if (!r || name === undefined) return null;
              return Object.prototype.hasOwnProperty.call(r.values, name) ? r.values[name] : null;
            },
          },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [newRows, nNew, st?.columns]
  );

  /// Same value on the whole rectangle (overlay on a multiple selection or
  /// Delete = NULL).
  const startEditCells = (
    rect: { x: number; y: number; width: number; height: number },
    value: PendingValue
  ) => void stage(rectCells(rect, () => value));

  /// Paste: rectangle of values anchored at [col, row], clipped to the grid.
  /// '' stays an empty string, never NULL (the Delete key deal).
  const startPaste = (row: number, col: number, values: string[][]) => {
    const width = values.reduce((m, r) => Math.max(m, r.length), 0);
    void stage(
      rectCells({ x: col, y: row, width, height: values.length }, (r, c) => values[r - row]?.[c - col])
    );
  };

  /// Cells of the rectangle (decision 12) clipped to the grid, with one
  /// value per cell (`undefined` = out of the batch).
  const rectCells = (
    rect: { x: number; y: number; width: number; height: number },
    valueAt: (row: number, col: number) => PendingValue | undefined
  ) => {
    const out: { row: number; col: number; value: PendingValue }[] = [];
    if (!st?.columns) return out;
    const rows = Math.min(rect.y + rect.height, st.rows + nNew);
    const ncols = Math.min(rect.x + rect.width, st.columns.length);
    for (let r = rect.y; r < rows; r++)
      for (let c = rect.x; c < ncols; c++) {
        const value = valueAt(r, c);
        if (value !== undefined) out.push({ row: r, col: c, value });
      }
    return out;
  };

  /// "Run" from the "View SQL" dialog.
  const runBatch = async () => {
    if (!batch || connId === null || batch.phase !== "confirm") return;
    setBatch({ ...batch, phase: "running", error: null });
    const cursor = gridRows.current?.cursorAfterSave() ?? null;
    try {
      const result = await ipc.tableWriteBatch(connId, table.schema, table.name, batch.writes, appendTo());
      const refreshed = isClean(result) && (await refreshSaved(batch.writes, result));
      settle(batch.writes, result);
      if (refreshed) keepCursor(cursor, batch.writes);
      setBatch((b) => (b ? { ...b, phase: "done", result, refreshed } : b));
    } catch (e) {
      setBatch((b) => (b ? { ...b, phase: "confirm", error: asErrorOut(e) } : b));
    }
  };

  const closeBatch = () => {
    if (batch?.phase === "running") return;
    const reloadNeeded = batch?.phase === "done" && !batch.refreshed;
    setBatch(null);
    if (reloadNeeded) reload();
  };

  // Trailing whitespace does not count: Enter would remove it without redoing anything.
  const whereDirty = whereDraft.trim() !== tq.where_sql;
  const commitWhere = (text: string) => {
    const where_sql = text.trim();
    setWhereDraft(where_sql);
    if (where_sql !== tq.where_sql) applyQuery({ ...tq, where_sql });
  };

  const commitFilter = (index: number | null, f: ColumnFilter) => {
    const filters = [...tq.filters];
    if (index === null) filters.push(f);
    else filters[index] = f;
    setDraft(null);
    applyQuery({ ...tq, filters });
  };

  // Always visible on the data: "+ Filter" must be found without knowing
  // the context menu.
  const queryBarVisible = tab.sub === "data";
  // Without a profile (tab never saved) the default has nowhere to live.
  const sortProfile = tab.profileId ?? conn?.profile.id ?? null;
  // Header menu: is the column already in the sort? are there others?
  const inSort = menu !== null && tq.order_by.some((o) => o.column === menu.column);
  const menuCol = menu !== null ? (st?.columns?.findIndex((c) => c.name === menu.column) ?? -1) : -1;
  const requestLocal = (desc: boolean | null) => {
    if (st?.resultId == null || menuCol < 0) return;
    setLocalReq({ resultId: st.resultId, col: menuCol, desc, nonce: Date.now() });
  };
  const serverSort: ServerSortProps = {
    order: tq.order_by,
    onHeaderSort: (col, additive) => {
      const name = st?.columns?.[col]?.name;
      if (name && !tab.running) void applyQuery({ ...tq, order_by: sortHeaderClick(tq.order_by, name, additive) });
    },
    localRequest: localReq,
    onLocalSortChange: setLocalSort,
  };
  const otherSorted = menu !== null && tq.order_by.some((o) => o.column !== menu.column);
  const filterColumns = st?.columns?.map((c) => c.name) ?? (cols.data ?? []).map((c) => c.name);
  // Suggestions of the WHERE bar: columns with their type, from
  // introspection or, if missing, from the result set. Memo: a new array at
  // every render would reconfigure the autocomplete and close the popup.
  const whereColumns = useMemo(
    () => cols.data ?? st?.columns?.map((c) => ({ name: c.name, type_display: c.type_display })) ?? [],
    [cols.data, st?.columns]
  );
  // The SELECT the tab is running: same generator as the backend.
  const tableSql = useQuery({
    queryKey: ["tableSql", connId, table.schema, table.name, JSON.stringify(tq)],
    queryFn: () => ipc.tableDataSql(connId!, table.schema, table.name, tq),
    enabled: connId !== null && tab.sub === "data",
    staleTime: Infinity,
  });

  return (
    <div className="results-pane">
      <div className="subtab-bar">
        {(tab.navBack.length > 0 || tab.navFwd.length > 0) && (
          <span className="table-nav">
            <button
              className="btn small"
              disabled={tab.navBack.length === 0 || tab.running}
              title={t("Back (⌥←)")}
              onClick={() => navStep(-1)}
            >
              <IconChevronLeft />
            </button>
            <button
              className="btn small"
              disabled={tab.navFwd.length === 0 || tab.running}
              title={t("Forward (⌥→)")}
              onClick={() => navStep(1)}
            >
              <IconChevronRight />
            </button>
            <span className="table-nav-trail">
              {tab.navBack.slice(-2).map((n, i) => (
                <span key={i}>{n.table.name} › </span>
              ))}
              <b>{table.name}</b>
            </span>
          </span>
        )}
        {SUBS.map((s) => (
          <button
            key={s.key}
            className={"subtab" + (tab.sub === s.key ? " active" : "")}
            onClick={() => useStore.getState().setSub(tab.id, s.key)}
          >
            {s.key === "ddl" ? s.label : t(s.label)}
          </button>
        ))}
        <div className="spacer" />
        {tab.sub === "data" && pkCols.length > 0 && !readOnly && (
          <span className="row-actions">
            <button
              className="btn small"
              title={t("Adds a new row below the selected one; it is written with Save (⌥Insert)")}
              disabled={connId === null || tab.running || saving || !st?.columns}
              onClick={addRow}
            >
              <IconPlus /> {t("Row")}
            </button>
            <button
              className="btn small"
              title={t("Duplicates the selected rows below them, with the key set to DEFAULT (⌃⌥Insert)")}
              disabled={connId === null || tab.running || saving || selRows.length === 0}
              onClick={() => void duplicateRows(selRows)}
            >
              <IconDuplicate /> {t("Duplicate")}
            </button>
            <button
              className="btn small"
              title={
                selAllDeleted
                  ? t("Unmarks the selected rows for deletion")
                  : t("Marks the selected rows for deletion; they are deleted with Save (Del)")
              }
              disabled={connId === null || tab.running || saving || selRows.length === 0}
              onClick={() => void deleteRows(selRows)}
            >
              <IconTrash /> {selAllDeleted ? t("Restore") : t("Delete")}
            </button>
          </span>
        )}
        {tab.sub === "data" && nUnsaved > 0 && (
          <span className="pending-bar">
            {nPending > 0 && (
              <span className="pending-count">
                {nPending === 1
                  ? t("1 unsaved change")
                  : t("{n} unsaved changes", { n: nPending.toLocaleString(locale()) })}
              </span>
            )}
            {nNew > 0 && (
              <span className="pending-count new-rows">
                {nNew === 1 ? t("1 new row") : t("{n} new rows", { n: nNew.toLocaleString(locale()) })}
              </span>
            )}
            {nDeleted > 0 && (
              <span className="pending-count deleted-rows">
                {nDeleted === 1
                  ? t("1 row to delete")
                  : t("{n} rows to delete", { n: nDeleted.toLocaleString(locale()) })}
              </span>
            )}
            <button
              className="btn small"
              title={t("Shows the statements that will run")}
              disabled={saving}
              onClick={() => void preview()}
            >
              {t("View SQL")}
            </button>
            <button
              className="btn small"
              title={t("Discards all unsaved changes")}
              disabled={saving}
              onClick={discard}
            >
              {t("Discard")}
            </button>
            <button
              className="btn small primary"
              title={t("Writes the changes to the database (⌘S)")}
              disabled={saving || tab.running}
              onClick={() => void save()}
            >
              {saving ? t("Saving…") : t("Save")}
            </button>
          </span>
        )}
        {tab.sub === "data" && more?.loading && (
          <span className="more-status muted" role="status">
            {t("loading more rows…")}
          </span>
        )}
        {tab.sub === "data" && more?.error && (
          <span className="more-status" role="alert" title={tMsg(more.error.message)}>
            {t("More rows not loaded")}
            <button className="btn small" onClick={() => loadMore(true)}>
              {t("Retry")}
            </button>
          </span>
        )}
        {tab.sub === "data" &&
          (tab.running ? (
            <button
              className="btn small"
              onClick={cancelLoad}
            >
              {t("Cancel")}
            </button>
          ) : (
            <button
              className="btn small"
              title={t("Reload data (F5)")}
              disabled={connId === null}
              onClick={() => void userReload()}
            >
              <IconRefresh />
            </button>
          ))}
        {tab.sub !== "data" && (
          <button
            className="btn small"
            title={tab.sub === "ddl" ? t("Reload DDL (F5)") : t("Reload structure (F5)")}
            disabled={connId === null || metaFetching}
            onClick={reloadMeta}
          >
            <IconRefresh />
          </button>
        )}
      </div>
      {queryBarVisible && (
        <div className="table-query-bar">
          <div className={whereDirty ? "where-box dirty" : "where-box"}>
            <span className="where-kw">WHERE</span>
            <WhereInput
              ref={whereRef}
              value={whereDraft}
              columns={whereColumns}
              dialect={conn?.profile.dialect ?? ""}
              disabled={tab.running}
              placeholder={t("e.g. status = 'A' AND amount > 100 — Enter to apply")}
              title={t(
                "Hand-written SQL condition, ANDed with the filters (⌘F). Enter applies, Shift+Enter adds a line, Esc cancels. Ctrl+. shows the columns."
              )}
              onChange={setWhereDraft}
              onCommit={commitWhere}
              onCancel={() => setWhereDraft(tq.where_sql)}
            />
            {/* Draft not applied: the dashed border is not enough to say what
                to do. The placeholder says it only with an empty field. */}
            {whereDirty && (
              <span className="where-hint" aria-live="polite">
                <kbd>{t("Enter")}</kbd> {t("apply")} · <kbd>Esc</kbd> {t("cancel")}
              </span>
            )}
            {(whereDraft !== "" || tq.where_sql !== "") && (
              <button
                className="chip-x"
                title={t("Remove the WHERE filter")}
                disabled={tab.running}
                onClick={(e) => {
                  e.preventDefault();
                  commitWhere("");
                }}
              >
                <IconX />
              </button>
            )}
          </div>
          {/* Two groups, in the order of the SELECT: first the filters (ANDed
              with the WHERE), then the sort with its default. */}
          <span className="query-group filter-group">
            <span
              className="query-group-icon"
              role="img"
              aria-label={t("Filters")}
              title={t("Server-side filters, combined with WHERE using AND")}
            >
              <IconFilter />
            </span>
            {tq.filters.map((f, i) => (
              <FilterChip
                key={`${f.column}:${i}`}
                filter={f}
                disabled={tab.running}
                onCommit={(next) => commitFilter(i, next)}
                onDraftChange={null}
                onRemove={() => applyQuery({ ...tq, filters: tq.filters.filter((_, j) => j !== i) })}
              />
            ))}
            {draft && (
              <FilterChip
                filter={draft}
                disabled={tab.running}
                autoFocus
                onCommit={(next) => commitFilter(null, next)}
                onDraftChange={setDraft}
                onRemove={() => setDraft(null)}
              />
            )}
            {!draft && (
              <FilterAdd
                ref={filterAddRef}
                columns={whereColumns}
                disabled={tab.running}
                onPick={(column) => setDraft({ column, op: "eq", value: "" })}
              />
            )}
            {tq.filters.length > 1 && (
              <button
                className="query-clear"
                disabled={tab.running}
                title={t("Remove all filters (WHERE stays)")}
                onClick={() => applyQuery({ ...tq, filters: [] })}
              >
                {t("Clear")}
              </button>
            )}
          </span>
          {whereColumns.length > 0 && (
            <span className="query-group sort-group">
              <span
                className="query-group-icon"
                role="img"
                aria-label={t("Sorting")}
                title={t("Server-side sort: \"Sort\" to choose the columns, or click the headers (⌘+click adds a column)")}
              >
                <IconSort />
              </span>
              <SortChips
                order={tq.order_by}
                disabled={tab.running}
                onChange={(order_by) => void applyQuery({ ...tq, order_by })}
              />
              <SortPanel
                order={tq.order_by}
                columns={whereColumns}
                disabled={tab.running}
                onApply={(order_by) => void applyQuery({ ...tq, order_by })}
              />
              <SortMenu
                profileId={sortProfile}
                schema={table.schema}
                table={table.name}
                order={tq.order_by}
                columns={filterColumns}
                disabled={tab.running}
                onApply={(order_by) => void applyQuery({ ...tq, order_by })}
              />
              {tq.order_by.length > 1 && (
                <button
                  className="query-clear"
                  disabled={tab.running}
                  title={t("Remove the whole sort")}
                  onClick={() => applyQuery({ ...tq, order_by: [] })}
                >
                  {t("Clear")}
                </button>
              )}
            </span>
          )}
          {tableSql.data && (
            <span className="table-sql">
              <SqlPreview sql={tableSql.data} dialect={conn?.profile.dialect ?? ""} />
              <button
                className="btn small"
                title={t("Opens this SELECT in an editable SQL tab")}
                onClick={() => newSqlTab(tableSql.data)}
              >
                {t("Open as query")}
              </button>
            </span>
          )}
        </div>
      )}
      {tab.sub === "data" &&
        (tab.running && (!st || st.resultId === null) ? (
          <RunningNotice label={t("Query running…")} startedAt={tab.startedAt} onCancel={cancelLoad} />
        ) : st ? (
          <StatementPane
            tab={tab}
            st={st}
            gridHost={gridHost}
            gridSize={gridSize}
            onHeaderContext={(col, x, y) => {
              const column = st.columns?.[col]?.name;
              if (column) setMenu({ column, x, y });
            }}
            editable={pkCols.length > 0 && !readOnly && !showingStale}
            onEditCell={(row, col, value) => void stage([{ row, col, value }])}
            pendingAt={pendingAt}
            canSetNull={cols_nullable}
            columnDefault={(column) => cols.data?.find((c) => c.name === column)?.default ?? null}
            onEditCells={startEditCells}
            onPasteCells={startPaste}
            cellActions={cellActions}
            linkCols={linkCols}
            onFollowLink={followLink}
            rowLinks={rowLinks}
            onNearEnd={loadMore}
            serverSort={serverSort}
            extraRows={extraRows}
            focusCell={focusCell}
            rowActions={rowActions}
            onFilterCell={(column, value, exclude) =>
              commitFilter(
                null,
                value === null
                  ? { column, op: exclude ? "is_not_null" : "is_null", value: "" }
                  : { column, op: exclude ? "ne" : "eq", value }
              )
            }
          />
        ) : loadError ? (
          <ErrorPanel error={loadError} />
        ) : connId === null ? (
          <div className="hint">{t("connection closed — reconnect the profile to see the data")}</div>
        ) : busy && busy.id !== tab.id ? (
          <RunningNotice
            label={t("Waiting for “{tab}”: the table tabs of a connection load one at a time.", {
              tab: busy.title,
            })}
            startedAt={null}
          />
        ) : connectingSince !== null ? (
          <RunningNotice label={t("Waiting for a connection to the server…")} startedAt={connectingSince} />
        ) : (
          <div className="hint">{t("loading…")}</div>
        ))}
      {tab.sub === "structure" &&
        (connId !== null ? (
          <StructurePane connId={connId} table={table} />
        ) : (
          <div className="hint">{t("connection closed — reconnect the profile")}</div>
        ))}
      {tab.sub === "ddl" &&
        (connId !== null ? (
          <DdlPane connId={connId} table={table} />
        ) : (
          <div className="hint">{t("connection closed — reconnect the profile")}</div>
        ))}
      {menu && (
        <div
          className="tab-menu"
          style={{ left: menu.x, top: menu.y }}
          onMouseDown={(e) => e.stopPropagation()}
        >
          <div className="tab-menu-label mono">{menu.column}</div>
          {(
            [
              [t("Sort on server ↑"), sortOnly(menu.column, false), true],
              [t("Sort on server ↓"), sortOnly(menu.column, true), true],
              // Adding makes sense only if there is already another column.
              [t("Add to sort ↑"), sortAdd(tq.order_by, menu.column, false), otherSorted],
              [t("Add to sort ↓"), sortAdd(tq.order_by, menu.column, true), otherSorted],
              [t("Remove from sort"), sortRemove(tq.order_by, menu.column), inSort && tq.order_by.length > 1],
              [t("Clear server sort"), [], tq.order_by.length > 0],
            ] as const
          )
            .filter(([, , show]) => show)
            .map(([label, order_by]) => (
              <button
                key={label}
                className="tab-menu-item"
                disabled={tab.running}
                onClick={() => {
                  applyQuery({ ...tq, order_by: [...order_by] });
                  setMenu(null);
                }}
              >
                {label}
              </button>
            ))}
          <div className="tab-menu-sep" />
          {/* Local sort: instant, but only on the rows already downloaded
              (with more pages on the server the notice appears). */}
          <button
            className="tab-menu-item"
            disabled={menuCol < 0}
            onClick={() => {
              requestLocal(false);
              setMenu(null);
            }}
          >
            {t("Sort only the fetched rows ⇡")}
          </button>
          <button
            className="tab-menu-item"
            disabled={menuCol < 0}
            onClick={() => {
              requestLocal(true);
              setMenu(null);
            }}
          >
            {t("Sort only the fetched rows ⇣")}
          </button>
          {localSort && (
            <button
              className="tab-menu-item"
              onClick={() => {
                requestLocal(null);
                setMenu(null);
              }}
            >
              {t("Remove the fetched-rows sort")}
            </button>
          )}
          <div className="tab-menu-sep" />
          <button
            className="tab-menu-item"
            disabled={tab.running}
            onClick={() => {
              setDraft({ column: menu.column, op: "eq", value: "" });
              setMenu(null);
            }}
          >
            {t("Filter on this column…")}
          </button>
        </div>
      )}
      {batch && (
        <BatchDialog
          batch={batch}
          target={`${table.schema}.${table.name}`}
          profile={conn?.profile ?? null}
          manualCommit={conn?.manualCommit ?? false}
          onRun={() => void runBatch()}
          onClose={closeBatch}
        />
      )}
    </div>
  );
}

/// Confirmation of the multi-cell batch (decision 12): target, count, exact
/// SQL. Outcome in the dialog itself: success, rows ≠ 1, error with an
/// indication of what happened to the transaction (atomic ROLLBACK on the
/// shared connection, open transaction on prod §9.7).
function BatchDialog({
  batch,
  target,
  profile,
  manualCommit,
  onRun,
  onClose,
}: {
  batch: BatchState;
  target: string;
  manualCommit: boolean;
  profile: Profile | null;
  onRun: () => void;
  onClose: () => void;
}) {
  const running = batch.phase === "running";
  const res = batch.result;
  const mismatches = res ? res.applied.filter((n) => n !== 1).length : 0;
  // Composition of the batch: UPDATEs only (historical texts) or mixed with
  // DELETE/INSERT. `nI` = statements that are not UPDATEs.
  const count = (k: TableWrite["kind"]) => batch.writes.filter((w) => w.kind === k).length;
  const nU = count("update");
  const nI = batch.writes.length - nU;
  const stmts = (
    [
      ["delete", "{n} DELETE"],
      ["update", "{n} UPDATE"],
      ["insert", "{n} INSERT"],
    ] as const
  )
    .filter(([k]) => count(k) > 0)
    .map(([k, label]) => t(label, { n: count(k).toLocaleString(locale()) }))
    .join(", ");
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Enter" && !e.metaKey && !e.ctrlKey && !e.altKey) {
        e.preventDefault();
        if (batch.phase === "confirm") onRun();
        else if (batch.phase === "done") onClose();
      } else if (e.key === "Escape") {
        e.preventDefault();
        onClose();
      }
      e.stopPropagation();
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [batch.phase, onRun, onClose]);
  return (
    <div className="dialog-overlay">
      <div className="dialog update-dialog">
        <div className="dialog-title">
          <span>
            {t("Confirm batch UPDATE")}
            {profile?.is_production && <span className="prod-tag"> {t("production")}</span>}
          </span>
          <button className="btn small dialog-close" disabled={running} onClick={onClose}>
            <IconX />
          </button>
        </div>
        <div className="dialog-body">
          <div className="update-target">
            <span className="mono">{target}</span>
            {profile && <span className="muted"> — {profile.name}</span>}
          </div>
          <div className="update-change">
            {nI === 0
              ? t("{cells} cells across {rows} rows — one UPDATE per row", {
                  cells: batch.cells.toLocaleString(locale()),
                  rows: nU.toLocaleString(locale()),
                })
              : t("{cells} changes — {stmts}, one per row", {
                  cells: batch.cells.toLocaleString(locale()),
                  stmts,
                })}
            {manualCommit
              ? t(", in the open transaction (Commit to apply)")
              : t(", in an atomic transaction")}
          </div>
          <pre className="ddl-pane update-sql">{batch.sql}</pre>
          {batch.error && <ErrorPanel error={batch.error} />}
          {res?.error && (
            <>
              <ErrorPanel error={res.error} />
              <div className="banner warn">
                {t(nI === 0 ? "UPDATE {n} of {total} failed." : "Statement {n} of {total} failed.", {
                  n: (res.error_index ?? 0) + 1,
                  total: batch.writes.length,
                })}{" "}
                {res.rolled_back
                  ? t("No changes applied: ROLLBACK, the database is unchanged.")
                  : res.in_transaction
                    ? t(
                        nI === 0
                          ? "The {n} successful UPDATEs remain in the open transaction: Commit or Rollback from the toolbar."
                          : "The {n} successful statements stay in the open transaction: Commit or Rollback from the toolbar.",
                        { n: res.applied.length }
                      )
                    : ""}
              </div>
            </>
          )}
          {res && !res.error && (
            <div className="banner ok">
              {t(nI === 0 ? "{n} UPDATEs executed" : "{n} statements executed", {
                n: res.applied.length.toLocaleString(locale()),
              })}
              {res.in_transaction ? t(" in the open transaction — Commit to apply.") : "."}
            </div>
          )}
          {mismatches > 0 && (
            <div className="banner warn">
              {t(
                "{n} UPDATEs with affected rows ≠ 1 (expected 1 per row): the rows may have changed underneath. The data will be reloaded.",
                { n: mismatches }
              )}
            </div>
          )}
          <div className="form-actions">
            <div className="spacer" />
            {batch.phase === "done" ? (
              <button className="btn primary" onClick={onClose}>
                {t("Close and reload")}
              </button>
            ) : (
              <>
                <button className="btn" disabled={running} onClick={onClose}>
                  {t("Cancel")}
                </button>
                <button className="btn primary" disabled={running} onClick={onRun}>
                  {running
                    ? t("Running…")
                    : nI === 0
                      ? t("Run {n} UPDATEs", { n: nU.toLocaleString(locale()) })
                      : t("Run: {stmts}", { stmts })}
                </button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}


/// Chip of a filter: operator and value. Changes re-query on commit (Enter,
/// blur with a changed value, operator without an operand); the draft does
/// not touch the server until confirmed.
function FilterChip({
  filter,
  disabled,
  autoFocus = false,
  onCommit,
  onDraftChange,
  onRemove,
}: {
  filter: ColumnFilter;
  disabled: boolean;
  autoFocus?: boolean;
  onCommit: (f: ColumnFilter) => void;
  /// Present only on the draft: updates without a re-query.
  onDraftChange: ((f: ColumnFilter) => void) | null;
  onRemove: () => void;
}) {
  const [value, setValue] = useState(filter.value);
  useEffect(() => setValue(filter.value), [filter.value]);
  const isDraft = onDraftChange !== null;

  const commitValue = () => {
    if (isDraft && value.trim() === "") return; // empty draft: stays a draft
    if (!isDraft && value === filter.value) return; // nothing to redo
    onCommit({ ...filter, value });
  };

  return (
    <span className="query-chip filter-chip">
      <span className="mono">{filter.column}</span>
      <select
        value={filter.op}
        disabled={disabled}
        onChange={(e) => {
          const op = e.target.value as FilterOp;
          if (!needsValue(op)) onCommit({ ...filter, op, value: "" });
          else if (isDraft) onDraftChange({ ...filter, op });
          else onCommit({ ...filter, op, value });
        }}
      >
        {OPS.map((o) => (
          <option key={o.op} value={o.op}>
            {o.label}
          </option>
        ))}
      </select>
      {needsValue(filter.op) && (
        <input
          className="mono"
          value={value}
          disabled={disabled}
          autoFocus={autoFocus}
          placeholder={t("value")}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") commitValue();
          }}
          onBlur={commitValue}
        />
      )}
      <button
        className="chip-x"
        title={t("Remove filter")}
        aria-label={t("Remove the filter on {col}", { col: filter.column })}
        disabled={disabled}
        onClick={onRemove}
      >
        <IconX />
      </button>
    </span>
  );
}

function StructurePane({ connId, table }: { connId: number; table: TableRef }) {
  // Same query key as the tree: shared cache, ⟳ invalidates both.
  const cols = useQuery({
    queryKey: ["columns", connId, table.schema, table.name],
    queryFn: () => ipc.schemaColumns(connId, table.schema, table.name),
    staleTime: Infinity,
  });
  if (cols.isLoading) return <div className="hint">{t("loading…")}</div>;
  if (cols.isError) return <div className="hint">{t("structure not available")}</div>;
  return (
    <div className="structure-pane">
      <table className="structure-table">
        <thead>
          <tr>
            <th>#</th>
            <th></th>
            <th>{t("Column")}</th>
            <th>{t("Type")}</th>
            <th>Nullable</th>
            <th>Default</th>
          </tr>
        </thead>
        <tbody>
          {cols.data?.map((c) => (
            <tr key={c.name}>
              <td className="num">{c.ordinal}</td>
              <td>{c.is_primary_key ? "⚿" : ""}</td>
              <td className="mono">{c.name}</td>
              <td className="mono">{c.type_display}</td>
              <td>{c.nullable ? t("yes") : t("no")}</td>
              <td className="mono muted">{c.default ?? ""}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function DdlPane({ connId, table }: { connId: number; table: TableRef }) {
  const ddl = useQuery({
    queryKey: ["ddl", connId, table.schema, table.name],
    queryFn: () => ipc.tableDdl(connId, table.schema, table.name),
    staleTime: Infinity,
  });
  if (ddl.isLoading) return <div className="hint">{t("loading…")}</div>;
  if (ddl.isError) return <div className="hint">{t("DDL not available")}</div>;
  return <pre className="ddl-pane">{ddl.data}</pre>;
}
